import type { Transaction } from "@/lib/models";

export interface MonthlySummary {
  key: string;
  month: string;
  income: number;
  expenses: number;
  savings: number;
  cashFlow: number;
}

export function getCurrencies(transactions: Transaction[]) {
  return [...new Set(transactions.map((transaction) => transaction.currency))].sort();
}

export function getLatestMonth(transactions: Transaction[]) {
  return transactions.reduce((latest, item) => item.date.slice(0, 7) > latest ? item.date.slice(0, 7) : latest, "");
}

export function summarizeMonth(transactions: Transaction[], month: string) {
  const monthTransactions = transactions.filter((item) => item.date.startsWith(month));
  const income = monthTransactions
    .filter((item) => item.type === "income")
    .reduce((sum, item) => sum + Math.abs(item.amount), 0);
  const refunds = monthTransactions
    .filter((item) => item.type === "refund")
    .reduce((sum, item) => sum + Math.abs(item.amount), 0);
  const spending = monthTransactions
    .filter((item) => item.type === "expense")
    .reduce((sum, item) => sum + Math.abs(item.amount), 0);
  const investmentPurchases = monthTransactions
    .filter((item) => item.type === "investment")
    .reduce((sum, item) => sum + Math.abs(item.amount), 0);
  const expenses = Math.max(0, spending - refunds);
  const savings = income - expenses;
  return { income, expenses, savings, cashFlow: savings - investmentPurchases, investmentPurchases, transactions: monthTransactions };
}

export function getMonthlySummaries(transactions: Transaction[], currency: string, endMonth: string): MonthlySummary[] {
  if (!endMonth) return [];
  const [year, month] = endMonth.split("-").map(Number);
  return Array.from({ length: 12 }, (_, index) => {
    const date = new Date(year, month - 1 - (11 - index), 1);
    const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
    const summary = summarizeMonth(transactions.filter((item) => item.currency === currency), key);
    return {
      key,
      month: date.toLocaleDateString("en-GB", { month: "short" }),
      income: summary.income,
      expenses: summary.expenses,
      savings: summary.savings,
      cashFlow: summary.cashFlow
    };
  });
}

export function getCategoryTotals(transactions: Transaction[]) {
  const totals = new Map<string, number>();
  for (const item of transactions) {
    if (item.type !== "expense") continue;
    totals.set(item.category, (totals.get(item.category) ?? 0) + Math.abs(item.amount));
  }
  return [...totals.entries()]
    .map(([name, value]) => ({ name, value }))
    .sort((a, b) => b.value - a.value);
}

export function detectRecurring(transactions: Transaction[]) {
  const groups = new Map<string, Transaction[]>();
  for (const transaction of transactions) {
    if (transaction.type !== "expense") continue;
    const key = `${transaction.merchant.toLowerCase() || transaction.description.toLowerCase()}|${transaction.currency}`;
    groups.set(key, [...(groups.get(key) ?? []), transaction]);
  }
  return [...groups.values()]
    .filter((group) => group.length >= 3)
    .map((group) => {
      const sorted = [...group].sort((a, b) => a.date.localeCompare(b.date));
      return {
        ...sorted[sorted.length - 1],
        isRecurring: true,
        occurrenceCount: group.length,
        averageAmount: group.reduce((sum, item) => sum + Math.abs(item.amount), 0) / group.length
      };
    })
    .sort((a, b) => b.averageAmount - a.averageAmount)
    .slice(0, 4);
}

export function formatMoney(value: number, currency: string, compact = false) {
  return new Intl.NumberFormat("en-CH", {
    style: "currency",
    currency,
    notation: compact ? "compact" : "standard",
    maximumFractionDigits: compact ? 1 : 0
  }).format(value);
}

export function monthLabel(key: string) {
  if (!key) return "your latest month";
  const [year, month] = key.split("-").map(Number);
  return new Date(year, month - 1, 1).toLocaleDateString("en-GB", { month: "long", year: "numeric" });
}
